const src = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const g = k => (src[k] !== undefined && src[k] !== null) ? src[k] : '';
return [{ json: {
  source: 'Website Form',
  firstName: g('First Name') || g('firstName'),
  lastName: g('Last Name') || g('lastName'),
  phone: g('Phone') || g('phone'),
  email: g('Email') || g('email'),
  address: g('Address') || g('address'),
  serviceNeeded: g('Service Needed') || g('serviceNeeded'),
  description: g('Description') || g('description'),
  photosLink: g('Photos Link') || g('photosLink'),
  preferredTime: g('Preferred Time') || g('preferredTime'),
  status: 'New'
}}];

const lead = $json;
const systemPrompt = `You are the lead-scoring engine for a roofing company in the Boston, Massachusetts area.
Score each inbound lead from 1 to 100 and classify temperature and urgency.

Scoring factors (weigh all):
- Urgency: an active leak, storm damage, or emergency is the highest signal. A routine inspection or general question is the lowest.
- Timeline: ASAP or this week is hot; within a month is warm; someday or just researching is cold.
- Service type: full roof replacement and storm or leak emergencies score highest; repairs are mid; inspections, gutters, and general inquiries are lower.
- Budget and ownership signals: a homeowner ready to move, an insurance claim, or any budget mention raises the score; renters or pure price-shopping lower it.
- Completeness: a full address plus phone plus a clear description is a stronger lead than a sparse one.

Temperature mapping: Hot = 80-100, Warm = 50-79, Cold = 1-49. Keep the number and the temperature consistent.
Urgency: Emergency, High, Medium, or Low.

Be decisive and realistic. Base the score only on the lead data provided. Do not invent facts. The summary and recommended_next_step are for the internal sales team, not the customer.`;
const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    lead_score: { type: 'integer' },
    temperature: { type: 'string', enum: ['Hot', 'Warm', 'Cold'] },
    urgency: { type: 'string', enum: ['Emergency', 'High', 'Medium', 'Low'] },
    detected_service: { type: 'string' },
    summary: { type: 'string' },
    recommended_next_step: { type: 'string' }
  },
  required: ['lead_score', 'temperature', 'urgency', 'detected_service', 'summary', 'recommended_next_step']
};
const userContent = `New roofing lead submitted via the website form. Score it.\n\n${JSON.stringify(lead, null, 2)}`;
return [{ json: { ...lead, systemPrompt, schema, userContent } }];

const resp = $json;
let txt = '';
if (Array.isArray(resp.content)) { const t = resp.content.find(b => b.type === 'text'); txt = t ? t.text : ''; }
let parsed = {};
try { parsed = JSON.parse(txt); } catch (e) { parsed = {}; }
const lead = $('Normalize Lead').first().json;
return [{ json: {
  ...lead,
  leadScore: parsed.lead_score !== undefined ? parsed.lead_score : '',
  temperature: parsed.temperature || '',
  urgency: parsed.urgency || '',
  serviceNeeded: lead.serviceNeeded || parsed.detected_service || '',
  logChannel: 'Website Form',
  logDirection: 'Inbound',
  logHandler: 'AI',
  logSummary: parsed.summary || 'Website form submitted',
  logNotes: 'Score ' + (parsed.lead_score !== undefined ? parsed.lead_score : 'n/a') + ' / ' + (parsed.temperature || '') + ' / Next: ' + (parsed.recommended_next_step || '')
}}];

const lead = $('Parse Score').first().json;
const leadId = $json.leadId || '';
const systemPrompt = `You write the instant confirmation text message a roofing company sends a customer right after they submit the website inspection-request form.
Rules:
- Warm, friendly, professional. Sound like a local Boston-area roofer, not a robot.
- Under 320 characters. One short paragraph.
- Greet them by first name if one is available.
- Confirm we received their request and reference their service need if it helps.
- Tell them a team member will reach out shortly to schedule their free inspection.
- No emojis. No links. Do not promise a specific price or appointment time.`;
const schema = { type: 'object', additionalProperties: false, properties: { message: { type: 'string' } }, required: ['message'] };
const userContent = JSON.stringify({ firstName: lead.firstName, serviceNeeded: lead.serviceNeeded, temperature: lead.temperature, company: 'YOUR_COMPANY_NAME' });
return [{ json: { ...lead, leadId, systemPrompt, schema, userContent } }];

const resp = $json;
let txt = '';
if (Array.isArray(resp.content)) { const t = resp.content.find(b => b.type === 'text'); txt = t ? t.text : ''; }
let msg = '';
try { msg = (JSON.parse(txt).message) || ''; } catch (e) { msg = txt || ''; }
const lead = $('Build Confirmation Request').first().json;
return [{ json: { ...lead, smsMessage: msg } }];
